suppressPackageStartupMessages({library(data.table);library(readxl)})
out<-'audit/20261011_all_groups_algorithm_audit/whole_proteome';root<-'/Users/gzy2520/Desktop/Research/kla/data'
e<-parse('R/candidate/prepare_sample_boxplot_inputs.R');for(x in e)if(is.call(x)&&as.character(x[[1]])=='<-'&&is.call(x[[3]])&&as.character(x[[3]][[1]])=='function')eval(x)
g<-fread('data/publication_input/human_ddr_go_annotations.tsv');ddr<-split_accessions(g[(is.na(get('TAXON ID'))|get('TAXON ID')==9606)&!grepl('(^|\\|)NOT($|\\|)',QUALIFIER)&get('GENE PRODUCT DB')=='UniProtKB'][['GENE PRODUCT ID']]);res<-list();removed<-list()
add<-function(group,variant,d,id,keep,p){a<-split_accessions(d[[id]][keep]);res[[length(res)+1]]<<-data.table(Group=group,Variant=variant,Rows=sum(keep),ProteinCount=length(a),DdrCount=sum(a%in%ddr),Fraction=100*sum(a%in%ddr)/length(a),SourceFile=p);a}
for(group in c('tendon','HepG2','sperm')){
 rel<-switch(group,tendon='PXD033146/search_results/extracted_pairing/search_result-HA119TQ/proteinGroups.txt',HepG2='PXD050147/search_results/SIRT_proteinGroups.txt',sperm='PXD066517/search_results/20240275.tsv');p<-file.path(root,rel);d<-fread(p,integer64='double');id<-if(group=='sperm')'PG.ProteinAccessions' else 'Majority protein IDs';valid<-if(group=='sperm')rep(TRUE,nrow(d)) else valid_maxquant_rows(d);a<-add(group,'all_valid_identified_rows',d,id,valid,p)
 cols<-switch(group,tendon=paste('Reporter intensity corrected',1:3),HepG2=grep('^Intensity (SIRT|WT)',names(d),value=TRUE),sperm=grep('PG.Quantity$',names(d),value=TRUE));pos<-Reduce(`|`,lapply(cols,function(j)positive_numeric(d[[j]])));b<-add(group,'any_positive_selected_samples',d,id,valid&pos,p);removed[[length(removed)+1]]<-data.table(Group=group,BaseAccession=setdiff(a,b),IsDdr=setdiff(a,b)%in%ddr,Reason='Absent from every selected positive-quantity sample')
 if(group=='tendon'){for(ch in list(4:6,1:6)){c<-paste('Reporter intensity corrected',ch);add(group,paste0('positive_channels_',paste(ch,collapse='_')),d,id,valid&Reduce(`|`,lapply(c,function(j)positive_numeric(d[[j]]))),p)}}
}
fwrite(rbindlist(res),file.path(out,'raw_selection_variant_counts.csv'));fwrite(rbindlist(removed),file.path(out,'identified_but_not_selected_ids.csv'))
mins<-list();inspect<-function(d,p,sh,cols){for(j in cols){v<-as.numeric(d[[j]]);mn<-min(v,na.rm=TRUE);tb<-sort(table(v),decreasing=TRUE);mins[[length(mins)+1]]<<-data.table(SourceFile=p,Sheet=sh,Column=j,Rows=length(v),Positive=sum(v>0,na.rm=TRUE),Minimum=mn,MinimumOccurrences=sum(v==mn,na.rm=TRUE),MostRepeatedValue=names(tb)[1],MostRepeatedCount=as.integer(tb[1]))}}
p<-file.path(root,'PXD050470/supplementary/prca2331-sup-0006-tables4.xlsx');d<-read_excel(p,skip=5);inspect(d,p,'Sheet1 skip5',paste0('Intensity_',c('H072','H081','H187')));capture.output(print(read_excel(p,col_names=FALSE,n_max=5),width=Inf),file=file.path(out,'hippocampus_workbook_preface.txt'))
p<-file.path(root,'PXD065775/search_results/20170330_01-24_patients_iTRAQ.xlsx');for(sh in c('ANTs','CISs')){d<-read_excel(p,sheet=sh);inspect(d,p,sh,c(paste0('Non-rec',1:4),paste0('Rec',1:4)))}
fwrite(rbindlist(mins),file.path(out,'complete_channel_minima_audit.csv'))
